<?php

use Modules\Core\Models\User;use Modules\Inventory\Services\InventoryTransactionService;use Modules\MasterData\Models\Color;use Modules\MasterData\Models\Colorway;use Modules\MasterData\Models\Customer;use Modules\MasterData\Models\CustomerAqlConfig;use Modules\MasterData\Models\Material;use Modules\MasterData\Models\Operation;use Modules\MasterData\Models\Size;use Modules\MasterData\Models\Style;use Modules\MasterData\Models\Supplier;use Modules\MasterData\Models\Uom;use Modules\MasterData\Models\Warehouse;use Modules\ProductDev\Models\CostSheet;use Modules\ProductDev\Services\BomService;use Modules\ProductDev\Services\RoutingService;use Modules\Production\Services\ProductionOrderService;use Modules\Purchasing\Services\PurchasingService;use Modules\Receiving\Models\FabricRoll;use Modules\Receiving\Services\ReceivingService;use Modules\Sales\Services\SalesOrderService;
function erpApprovedStyle(User$u,float$qtyPerPcs=2.0,float$smv=15):array{$m=Uom::create(['company_id'=>1,'code'=>'MTR'.substr(uniqid(),-3),'name'=>'Meter']);$f=Material::create(['company_id'=>1,'code'=>'FAB-'.uniqid(),'name'=>'Kain','type'=>'FABRIC','tracking_level'=>'LOT']);$s=Style::create(['company_id'=>1,'style_no'=>'ST-'.uniqid(),'category'=>'WOVEN']);$bs=app(BomService::class);$bv=$bs->createVersion($s->id,[['material_id'=>$f->id,'qty_per_pcs'=>$qtyPerPcs,'uom_id'=>$m->id]],$u);$bs->markApproved($bv);$op=Operation::create(['company_id'=>1,'code'=>'OP-'.uniqid(),'name'=>'Jahit']);$rs=app(RoutingService::class);$rv=$rs->createVersion($s->id,[['operation_id'=>$op->id,'smv'=>$smv]],$u);$rs->markApproved($rv);CostSheet::create(['company_id'=>1,'doc_no'=>'COST-'.uniqid(),'style_id'=>$s->id,'bom_version_id'=>$bv->id,'routing_version_id'=>$rv->id,'version'=>1,'fabric_cost'=>$qtyPerPcs,'cm_cost'=>1,'overhead_cost'=>.5,'fob_price'=>$qtyPerPcs+2,'status'=>'APPROVED','created_by'=>$u->id]);return[$s,$f,$m];}
function erpConfirmedSo(User$u,Style$s,float$qty=100,float$price=15,?Customer$c=null):array{$c=$c??Customer::create(['company_id'=>1,'code'=>'C-'.uniqid(),'name'=>'Buyer']);$color=Color::create(['company_id'=>1,'code'=>'CLR'.substr(uniqid(),-2),'name'=>'Black']);$cw=Colorway::create(['company_id'=>1,'style_id'=>$s->id,'color_id'=>$color->id]);$size=Size::create(['company_id'=>1,'code'=>'SZ'.substr(uniqid(),-2)]);$svc=app(SalesOrderService::class);$so=$svc->create(1,['customer_id'=>$c->id,'order_date'=>now()->toDateString()],[['style_id'=>$s->id,'colorway_id'=>$cw->id,'size_id'=>$size->id,'qty'=>$qty,'price'=>$price]],$u);$so->update(['status'=>'APPROVED']);return[$svc->confirm($so),$cw,$size,$c];}
function qcFixture(float$qty=1200):array{$u=User::factory()->create(['company_id'=>1]);$c=Customer::create(['company_id'=>1,'code'=>'C-'.uniqid(),'name'=>'Buyer A','shipment_tolerance_pct'=>5]);CustomerAqlConfig::create(['company_id'=>1,'customer_id'=>$c->id,'inspection_level'=>'G2','aql_major'=>2.5,'aql_minor'=>4,'aql_critical'=>0]);[$s]=erpApprovedStyle($u);$s->update(['customer_id'=>$c->id]);[$so,$cw,$size]=erpConfirmedSo($u,$s,$qty,15,$c);$mo=app(ProductionOrderService::class)->createFromSalesOrder($so,$u)[0];$mo->update(['status'=>'FINISHING','qty_produced'=>$qty]);return[$u,$c,$s,$so,$mo->fresh(),$cw,$size];}
function packFixture(float$qty=100,float$tolerance=5):array{[$u,$c,$s,$so,$mo,$cw,$size]=qcFixture($qty);$so->update(['tolerance_pct'=>$tolerance]);$fg=Warehouse::create(['company_id'=>1,'code'=>'FG-'.substr(uniqid(),-3),'name'=>'Gudang FG','type'=>'FG']);Uom::firstOrCreate(['company_id'=>1,'code'=>'PCS'],['name'=>'Pcs']);return[$u,$c,$s,$so->fresh(),$mo->fresh(),$cw,$size,$fg];}
function shopFixture():array{$u=User::factory()->create(['company_id'=>1]);$m=Uom::create(['company_id'=>1,'code'=>'MTR'.substr(uniqid(),-3),'name'=>'Meter']);$pcs=Uom::create(['company_id'=>1,'code'=>'PCS'.substr(uniqid(),-3),'name'=>'Pcs']);$f=Material::create(['company_id'=>1,'code'=>'FAB-'.uniqid(),'name'=>'Twill','type'=>'FABRIC','tracking_level'=>'ROLL','gsm'=>200,'width_cm'=>150,'buy_uom_id'=>$m->id,'use_uom_id'=>$m->id]);$trim=Material::create(['company_id'=>1,'code'=>'TRM-'.uniqid(),'name'=>'Label','type'=>'TRIM','tracking_level'=>'LOT','use_uom_id'=>$pcs->id]);$s=Style::create(['company_id'=>1,'style_no'=>'ST-'.uniqid(),'category'=>'WOVEN']);$bs=app(BomService::class);$bv=$bs->createVersion($s->id,[['material_id'=>$f->id,'qty_per_pcs'=>2,'uom_id'=>$m->id,'is_backflush'=>false],['material_id'=>$trim->id,'qty_per_pcs'=>5,'uom_id'=>$pcs->id,'is_backflush'=>true]],$u);$bs->markApproved($bv);$op1=Operation::create(['company_id'=>1,'code'=>'OP1-'.uniqid(),'name'=>'Jahit sisi']);$op2=Operation::create(['company_id'=>1,'code'=>'OP2-'.uniqid(),'name'=>'Pasang lengan']);$rs=app(RoutingService::class);$rv=$rs->createVersion($s->id,[['operation_id'=>$op1->id,'smv'=>6,'seq'=>1],['operation_id'=>$op2->id,'smv'=>8,'seq'=>2]],$u);$rs->markApproved($rv);CostSheet::create(['company_id'=>1,'doc_no'=>'COST-'.uniqid(),'style_id'=>$s->id,'bom_version_id'=>$bv->id,'routing_version_id'=>$rv->id,'version'=>1,'fabric_cost'=>2,'trim_cost'=>.5,'cm_cost'=>1.4,'overhead_cost'=>.7,'fob_price'=>6,'status'=>'APPROVED','created_by'=>$u->id]);[$so,$cw,$size]=erpConfirmedSo($u,$s,100,15);$w=Warehouse::create(['company_id'=>1,'code'=>'RM-'.substr(uniqid(),-3),'name'=>'RM','type'=>'RM']);$its=app(InventoryTransactionService::class);$its->post('OPENING',['company_id'=>1,'source_document_type'=>'tests','source_document_id'=>1],[['material_id'=>$trim->id,'warehouse_id'=>$w->id,'qty'=>1000,'uom_id'=>$pcs->id,'unit_cost'=>.1]],$u);$sup=Supplier::create(['company_id'=>1,'code'=>'SUP-'.uniqid(),'name'=>'Tex','type'=>'FABRIC']);$po=app(PurchasingService::class)->createPo(1,['supplier_id'=>$sup->id,'order_date'=>now()->toDateString()],[['material_id'=>$f->id,'qty'=>500,'uom_id'=>$m->id,'unit_price'=>10]],$u);$po->update(['status'=>'APPROVED']);$gr=app(ReceivingService::class)->createAndPost(1,['purchase_order_id'=>$po->id,'warehouse_id'=>$w->id,'received_date'=>now()->toDateString()],[['po_line_id'=>$po->lines->first()->id,'qty_received'=>500,'rolls'=>[['roll_no'=>'R001','qty_buy'=>300,'qty_meter_actual'=>300],['roll_no'=>'R002','qty_buy'=>200,'qty_meter_actual'=>200]]]],$u);$gl=$gr->lines->first();foreach(FabricRoll::where('gr_line_id',$gl->id)->get()as$r){$its->releaseQualityHold(1,['material_id'=>$f->id,'warehouse_id'=>$w->id,'roll_id'=>$r->id,'uom_id'=>$m->id,'source_document_id'=>$gl->id],(float)$r->qty_buy,$u);$r->update(['status'=>'RELEASED']);}$svc=app(ProductionOrderService::class);$mo=$svc->release($svc->createFromSalesOrder($so,$u)[0],$w->id,$u);return[$u,$f,$trim,$m,$pcs,$w,$mo,$op1,$op2,$cw,$size];}
